--
-- Name: close_patient_care_after_death_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_patient_care_after_death_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  should_close BOOLEAN := FALSE;
BEGIN
  IF NEW.halal_datum IS NOT NULL THEN
    IF TG_OP = 'INSERT' THEN
      should_close := TRUE;
    ELSIF OLD.halal_datum IS DISTINCT FROM NEW.halal_datum THEN
      should_close := TRUE;
    END IF;
  END IF;

  IF should_close THEN
    UPDATE patient_episodes
       SET status = 'closed',
           closed_at = COALESCE(closed_at, CURRENT_TIMESTAMP)
     WHERE patient_id = NEW.id
       AND status = 'open';

    UPDATE episode_tasks et
       SET completed_at = COALESCE(et.completed_at, CURRENT_TIMESTAMP)
      FROM patient_episodes pe
     WHERE et.episode_id = pe.id
       AND pe.patient_id = NEW.id
       AND et.completed_at IS NULL;

    UPDATE slot_intents si
       SET state = 'expired',
           updated_at = CURRENT_TIMESTAMP
      FROM patient_episodes pe
     WHERE si.episode_id = pe.id
       AND pe.patient_id = NEW.id
       AND si.state = 'open';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: drop_old_event_partitions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_old_event_partitions(retention_days integer DEFAULT 1095) RETURNS TABLE(dropped_table text, partition_month date)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    r RECORD;
    cutoff DATE := (CURRENT_DATE - (retention_days || ' days')::interval);
    part_month DATE;
    m TEXT[];
BEGIN
    FOR r IN (
        SELECT child.relname AS partition_name
        FROM pg_inherits
        JOIN pg_class parent ON pg_inherits.inhparent = parent.oid
        JOIN pg_class child ON pg_inherits.inhrelid = child.oid
        WHERE parent.relname IN ('appointment_status_events', 'slot_state_events', 'provider_assignment_events')
    ) LOOP
        -- Extract YYYY_MM from partition name (e.g. ..._2020_01)
        m := regexp_match(r.partition_name, '_(\d{4})_(\d{2})$');
        IF m IS NOT NULL AND array_length(m, 1) >= 2 THEN
            part_month := (m[1] || '-' || m[2] || '-01')::date;
            -- Partition holds data for part_month; upper bound is part_month + 1.
            -- Drop if part_month + 1 month < cutoff (i.e. partition completely before cutoff)
            IF (part_month + INTERVAL '1 month')::DATE <= cutoff THEN
                BEGIN
                    EXECUTE format('DROP TABLE IF EXISTS %I CASCADE', r.partition_name);
                    dropped_table := r.partition_name;
                    partition_month := part_month;
                    RETURN NEXT;
                EXCEPTION WHEN OTHERS THEN
                    RAISE NOTICE 'Could not drop partition %: %', r.partition_name, SQLERRM;
                END;
            END IF;
        END IF;
    END LOOP;
END;
$_$;


