--
-- Name: prevent_open_episode_for_deceased_patient(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_open_episode_for_deceased_patient() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  patient_death_date DATE;
BEGIN
  IF NEW.status = 'open' THEN
    -- A beteg sorának zárolása megszünteti a halálozás-rögzítés és az
    -- epizódnyitás közötti versenyhelyzetet.
    SELECT p.halal_datum
      INTO patient_death_date
      FROM patients p
     WHERE p.id = NEW.patient_id
     FOR UPDATE;

    IF patient_death_date IS NOT NULL THEN
      RAISE EXCEPTION 'Elhunyt beteghez nem nyitható ellátási epizód.'
        USING ERRCODE = '23514',
              CONSTRAINT = 'patient_episodes_deceased_patient_guard';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_open_intent_for_inactive_episode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_open_intent_for_inactive_episode() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  episode_status TEXT;
  patient_death_date DATE;
BEGIN
  IF NEW.state = 'open' THEN
    SELECT pe.status, p.halal_datum
      INTO episode_status, patient_death_date
      FROM patient_episodes pe
      JOIN patients p ON p.id = pe.patient_id
     WHERE pe.id = NEW.episode_id
     FOR UPDATE OF p;

    IF episode_status IS DISTINCT FROM 'open' OR patient_death_date IS NOT NULL THEN
      RAISE EXCEPTION 'Lezárt vagy elhunyt beteg epizódjához nem hozható létre nyitott ütemezési szándék.'
        USING ERRCODE = '23514',
              CONSTRAINT = 'slot_intents_active_episode_guard';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_pending_task_for_inactive_episode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_pending_task_for_inactive_episode() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  episode_status TEXT;
  patient_death_date DATE;
BEGIN
  IF NEW.completed_at IS NULL THEN
    SELECT pe.status, p.halal_datum
      INTO episode_status, patient_death_date
      FROM patient_episodes pe
      JOIN patients p ON p.id = pe.patient_id
     WHERE pe.id = NEW.episode_id
     FOR UPDATE OF p;

    IF episode_status IS DISTINCT FROM 'open' OR patient_death_date IS NOT NULL THEN
      RAISE EXCEPTION 'Lezárt vagy elhunyt beteg epizódjához nem hozható létre aktív feladat.'
        USING ERRCODE = '23514',
              CONSTRAINT = 'episode_tasks_active_episode_guard';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


