-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Szerver-kezelte mellék-írás: őrizzük meg az optimista zár tokenjét.
    IF current_setting('app.skip_updated_at', true) = 'on' THEN
        RETURN NEW;
    END IF;
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: activity_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.activity_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_email text,
    action text NOT NULL,
    detail text,
    ip_address text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: admin_notification_batch_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_notification_batch_state (
    id integer NOT NULL,
    last_sent_at timestamp with time zone,
    CONSTRAINT admin_notification_batch_state_id_check CHECK ((id = 1))
);


--
-- Name: admin_notification_queue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_notification_queue (
    id integer NOT NULL,
    notification_type character varying(50) NOT NULL,
    summary_text text NOT NULL,
    detail_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    processed boolean DEFAULT false NOT NULL,
    processed_at timestamp with time zone
);


--
-- Name: admin_notification_queue_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.admin_notification_queue_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: admin_notification_queue_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.admin_notification_queue_id_seq OWNED BY public.admin_notification_queue.id;


--
-- Name: algorithm_registry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.algorithm_registry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    algorithm_code character varying(64) NOT NULL,
    version_label character varying(32) NOT NULL,
    description text,
    spec_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: analysis_export_subjects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_export_subjects (
    export_id uuid NOT NULL,
    patient_id uuid NOT NULL,
    anonymized_subject_key character varying(64) NOT NULL
);


--
-- Name: analysis_exports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_exports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    export_label character varying(128) NOT NULL,
    schema_version character varying(32) NOT NULL,
    query_definition jsonb NOT NULL,
    filter_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    row_count integer,
    content_hash character varying(128) NOT NULL,
    manifest_hash character varying(128),
    checksum_hierarchy jsonb DEFAULT '{}'::jsonb,
    storage_uri text,
    status character varying(20) DEFAULT 'completed'::character varying NOT NULL,
    created_by character varying(255),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    exported_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT analysis_exports_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'tombstoned'::character varying])::text[])))
);


--
-- Name: analysis_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analysis_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    study_id uuid NOT NULL,
    requested_by character varying(255) NOT NULL,
    purpose text,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT analysis_requests_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'completed'::character varying])::text[])))
);


