--
-- Name: appointments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.appointments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    patient_id uuid NOT NULL,
    time_slot_id uuid NOT NULL,
    created_by character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    alternative_time_slot_ids jsonb DEFAULT '[]'::jsonb,
    current_alternative_index integer,
    approved_at timestamp with time zone,
    approval_status character varying(20),
    approval_token character varying(255),
    dentist_email character varying(255),
    google_calendar_event_id character varying(255),
    appointment_status character varying(30),
    completion_notes text,
    is_late boolean DEFAULT false,
    appointment_type character varying(30),
    episode_id uuid,
    duration_minutes integer DEFAULT 30 NOT NULL,
    pool character varying(16) DEFAULT 'work'::character varying NOT NULL,
    no_show_risk numeric(3,2) DEFAULT 0 NOT NULL,
    requires_confirmation boolean DEFAULT false NOT NULL,
    confirmed_at timestamp with time zone,
    hold_expires_at timestamp with time zone,
    created_via character varying(30) DEFAULT 'migration'::character varying NOT NULL,
    override_reason text,
    requires_precommit boolean DEFAULT false NOT NULL,
    start_time timestamp with time zone,
    end_time timestamp with time zone,
    is_future boolean DEFAULT false,
    is_active_status boolean DEFAULT true,
    slot_intent_id uuid,
    step_code character varying(80),
    step_seq integer,
    plan_item_id uuid,
    plan_item_link_batch_id uuid,
    plan_item_linked_at timestamp with time zone,
    is_chain_reservation boolean DEFAULT false NOT NULL,
    work_phase_id uuid,
    attempt_number integer DEFAULT 1 NOT NULL,
    attempt_failed_reason text,
    attempt_failed_at timestamp with time zone,
    attempt_failed_by character varying(255),
    domain_revision bigint DEFAULT 1 NOT NULL,
    recorded_at timestamp with time zone,
    effective_at timestamp with time zone,
    type_label character varying(120),
    CONSTRAINT appointments_appointment_status_check CHECK (((appointment_status IS NULL) OR ((appointment_status)::text = ANY ((ARRAY['cancelled_by_doctor'::character varying, 'cancelled_by_patient'::character varying, 'completed'::character varying, 'no_show'::character varying, 'unsuccessful'::character varying])::text[])))),
    CONSTRAINT appointments_appointment_type_check CHECK (((appointment_type)::text = ANY ((ARRAY['elso_konzultacio'::character varying, 'munkafazis'::character varying, 'kontroll'::character varying, 'recall'::character varying, 'egyeb'::character varying])::text[]))),
    CONSTRAINT appointments_approval_status_check CHECK (((approval_status)::text = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying])::text[]))),
    CONSTRAINT appointments_created_via_check CHECK (((created_via)::text = ANY ((ARRAY['worklist'::character varying, 'patient_self'::character varying, 'admin_override'::character varying, 'surgeon_override'::character varying, 'migration'::character varying, 'google_import'::character varying])::text[]))),
    CONSTRAINT appointments_no_show_risk_check CHECK (((no_show_risk >= (0)::numeric) AND (no_show_risk <= (1)::numeric))),
    CONSTRAINT appointments_pool_check CHECK (((pool)::text = ANY ((ARRAY['consult'::character varying, 'work'::character varying, 'control'::character varying])::text[])))
);


--
-- Name: TABLE appointments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.appointments IS 'Időpont foglalások, amelyeket a beutaló orvosok hozhatnak létre';


--
-- Name: COLUMN appointments.patient_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.patient_id IS 'A beteg ID-ja';


--
-- Name: COLUMN appointments.time_slot_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.time_slot_id IS 'A lefoglalt időpont ID-ja';


--
-- Name: COLUMN appointments.created_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.created_by IS 'A beutaló orvos vagy admin email címe, aki lefoglalta az időpontot';


--
-- Name: COLUMN appointments.alternative_time_slot_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.alternative_time_slot_ids IS 'Alternatív időpontok ID-k tömbje (JSONB), amelyeket a betegnek fel lehet ajánlani';


--
-- Name: COLUMN appointments.current_alternative_index; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.current_alternative_index IS 'Jelenleg mutatott alternatív időpont indexe (NULL = elsődleges időpont, 0 = első alternatíva, stb.)';


--
-- Name: COLUMN appointments.approved_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.approved_at IS 'Időpont, amikor a feltételes időpontot a beteg elfogadta';


--
-- Name: COLUMN appointments.approval_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.approval_status IS 'Feltételes időpontválasztás státusza: pending (várakozik), approved (elfogadva), rejected (elvetve), NULL (normál időpont)';


--
-- Name: COLUMN appointments.approval_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.approval_token IS 'Biztonságos token az email linkekhez az időpont elfogadásához/elvetéséhez';


--
-- Name: COLUMN appointments.dentist_email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.dentist_email IS 'A fogpótlástanász email címe, aki kiírta az időpontot';


--
-- Name: COLUMN appointments.google_calendar_event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.google_calendar_event_id IS 'Google Calendar esemény ID (a Google Calendar API-ból kapott event ID)';


--
-- Name: COLUMN appointments.appointment_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.appointment_status IS 'Időpont státusza: cancelled_by_doctor (lemondta az orvos), cancelled_by_patient (lemondta a beteg), completed (sikeresen teljesült), no_show (nem jelent meg), NULL (normál/várható időpont)';


--
-- Name: COLUMN appointments.completion_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.completion_notes IS 'Rövid leírás arról, hogy mi történt az időpont során (sikeresen teljesült esetén)';


--
-- Name: COLUMN appointments.is_late; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.is_late IS 'Igaz, ha a beteg késett az időpontra';


--
-- Name: COLUMN appointments.appointment_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.appointment_type IS 'Időpont típusa: elso_konzultacio (első konzultáció), munkafazis (munkafázis - valami készül, ez a vizit egy lépcsője), kontroll (már kész van minden vagy legalábbis egy milestone-on túl vagyunk), NULL (nincs megadva)';


--
-- Name: COLUMN appointments.is_chain_reservation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.is_chain_reservation IS 'True when created via batch chain booking; excluded from one-hard-next partial unique index.';


--
-- Name: COLUMN appointments.work_phase_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.work_phase_id IS 'Canonical link to episode_work_phases.id. Nullable for backward compat (legacy rows still keyed via step_code/step_seq). Populated by 025 backfill and by new booking writes.';


--
-- Name: COLUMN appointments.attempt_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.attempt_number IS 'Hányadik próbálkozás ez a (episode_id, step_code) párra. Az első foglalás 1, minden további új próba +1. A lib/appointment-service.ts és lib/convert-slot-intent.ts számolja max(attempt_number)+1 alapján.';


--
-- Name: COLUMN appointments.attempt_failed_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.attempt_failed_reason IS 'Ha kitöltött, a próba sikertelen volt — `appointment_status = ''unsuccessful''` mellett kötelező. Későbbi klinikai elemzéshez (gyakori sikertelenségi okok).';


--
-- Name: COLUMN appointments.attempt_failed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.attempt_failed_at IS 'Mikor jelölte sikertelennek — audit log.';


--
-- Name: COLUMN appointments.attempt_failed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.attempt_failed_by IS 'Ki jelölte sikertelennek (felhasználó email-je) — audit log.';


--
-- Name: COLUMN appointments.type_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointments.type_label IS 'Szabad szöveges címke az időpont típusához (catch-all, főleg appointment_type=egyeb/recall esetén), pl. „implantátum kontroll 6h”.';


