-- Name: feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_email text,
    type character varying(50) NOT NULL,
    title character varying(255),
    description text NOT NULL,
    error_log text,
    error_stack text,
    user_agent text,
    url text,
    status character varying(20) DEFAULT 'open'::character varying,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    admin_response text,
    admin_note text,
    responded_at timestamp with time zone,
    responded_by text,
    ai_draft_response text,
    ai_draft_at timestamp with time zone,
    priority character varying(20) DEFAULT 'medium'::character varying NOT NULL,
    priority_score smallint DEFAULT 40 NOT NULL,
    priority_reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    triaged_at timestamp with time zone,
    triage_worker_claim_hash character varying(64),
    triage_worker_claimed_at timestamp with time zone,
    triage_worker_claim_expires_at timestamp with time zone,
    triage_worker_attempts integer DEFAULT 0 NOT NULL,
    triage_worker_last_result jsonb,
    CONSTRAINT feedback_priority_check CHECK (((priority)::text = ANY ((ARRAY['critical'::character varying, 'high'::character varying, 'medium'::character varying, 'low'::character varying])::text[]))),
    CONSTRAINT feedback_priority_score_check CHECK (((priority_score >= 0) AND (priority_score <= 100))),
    CONSTRAINT feedback_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'in_progress'::character varying, 'resolved'::character varying, 'closed'::character varying])::text[]))),
    CONSTRAINT feedback_type_check CHECK (((type)::text = ANY ((ARRAY['bug'::character varying, 'error'::character varying, 'crash'::character varying, 'suggestion'::character varying, 'other'::character varying])::text[])))
);


