--
-- Name: messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    patient_id uuid NOT NULL,
    sender_type public.sender_type_enum NOT NULL,
    sender_id uuid NOT NULL,
    sender_email text NOT NULL,
    subject text,
    message text NOT NULL,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    recipient_doctor_id uuid,
    reply_to_message_id uuid,
    client_message_id text,
    delivery_status text DEFAULT 'sent'::text NOT NULL,
    failed_reason text,
    search_vector tsvector GENERATED ALWAYS AS ((setweight(to_tsvector('hungarian'::regconfig, COALESCE(subject, ''::text)), 'A'::"char") || setweight(to_tsvector('hungarian'::regconfig, COALESCE(message, ''::text)), 'B'::"char"))) STORED
);


