-- Name: ohip14_responses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ohip14_responses (
    id uuid DEFAULT public.generate_uuid() NOT NULL,
    patient_id uuid NOT NULL,
    episode_id uuid,
    timepoint character varying(2) NOT NULL,
    completed_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    completed_by_patient boolean DEFAULT true,
    q1_functional_limitation integer,
    q2_functional_limitation integer,
    q3_physical_pain integer,
    q4_physical_pain integer,
    q5_psychological_discomfort integer,
    q6_psychological_discomfort integer,
    q7_physical_disability integer,
    q8_physical_disability integer,
    q9_psychological_disability integer,
    q10_psychological_disability integer,
    q11_social_disability integer,
    q12_social_disability integer,
    q13_handicap integer,
    q14_handicap integer,
    total_score integer,
    functional_limitation_score integer,
    physical_pain_score integer,
    psychological_discomfort_score integer,
    physical_disability_score integer,
    psychological_disability_score integer,
    social_disability_score integer,
    handicap_score integer,
    notes text,
    locked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    created_by character varying(255),
    updated_by character varying(255),
    stage_code character varying(50),
    CONSTRAINT ohip14_responses_q10_psychological_disability_check CHECK (((q10_psychological_disability >= 0) AND (q10_psychological_disability <= 4))),
    CONSTRAINT ohip14_responses_q11_social_disability_check CHECK (((q11_social_disability >= 0) AND (q11_social_disability <= 4))),
    CONSTRAINT ohip14_responses_q12_social_disability_check CHECK (((q12_social_disability >= 0) AND (q12_social_disability <= 4))),
    CONSTRAINT ohip14_responses_q13_handicap_check CHECK (((q13_handicap >= 0) AND (q13_handicap <= 4))),
    CONSTRAINT ohip14_responses_q14_handicap_check CHECK (((q14_handicap >= 0) AND (q14_handicap <= 4))),
    CONSTRAINT ohip14_responses_q1_functional_limitation_check CHECK (((q1_functional_limitation >= 0) AND (q1_functional_limitation <= 4))),
    CONSTRAINT ohip14_responses_q2_functional_limitation_check CHECK (((q2_functional_limitation >= 0) AND (q2_functional_limitation <= 4))),
    CONSTRAINT ohip14_responses_q3_physical_pain_check CHECK (((q3_physical_pain >= 0) AND (q3_physical_pain <= 4))),
    CONSTRAINT ohip14_responses_q4_physical_pain_check CHECK (((q4_physical_pain >= 0) AND (q4_physical_pain <= 4))),
    CONSTRAINT ohip14_responses_q5_psychological_discomfort_check CHECK (((q5_psychological_discomfort >= 0) AND (q5_psychological_discomfort <= 4))),
    CONSTRAINT ohip14_responses_q6_psychological_discomfort_check CHECK (((q6_psychological_discomfort >= 0) AND (q6_psychological_discomfort <= 4))),
    CONSTRAINT ohip14_responses_q7_physical_disability_check CHECK (((q7_physical_disability >= 0) AND (q7_physical_disability <= 4))),
    CONSTRAINT ohip14_responses_q8_physical_disability_check CHECK (((q8_physical_disability >= 0) AND (q8_physical_disability <= 4))),
    CONSTRAINT ohip14_responses_q9_psychological_disability_check CHECK (((q9_psychological_disability >= 0) AND (q9_psychological_disability <= 4))),
    CONSTRAINT ohip14_responses_timepoint_check CHECK (((timepoint)::text = ANY ((ARRAY['T0'::character varying, 'T1'::character varying, 'T2'::character varying, 'T3'::character varying, 'T4'::character varying, 'T5'::character varying])::text[])))
);


--
