--
-- Name: patient_anamnesis; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.patient_anamnesis (
    patient_id uuid NOT NULL,
    kezelesre_erkezes_indoka character varying(100),
    alkoholfogyasztas text,
    dohanyzas_szam character varying(50),
    maxilladefektus_van boolean DEFAULT false,
    brown_fuggoleges_osztaly character varying(1),
    brown_vizszintes_komponens character varying(1),
    mandibuladefektus_van boolean DEFAULT false,
    kovacs_dobak_osztaly character varying(1),
    nyelvmozgasok_akadalyozottak boolean DEFAULT false,
    gombocos_beszed boolean DEFAULT false,
    nyalmirigy_allapot character varying(30),
    fabian_fejerdy_protetikai_osztaly character varying(10),
    fabian_fejerdy_protetikai_osztaly_felso character varying(10),
    fabian_fejerdy_protetikai_osztaly_also character varying(10),
    radioterapia boolean DEFAULT false,
    radioterapia_dozis character varying(50),
    radioterapia_datum_intervallum character varying(100),
    chemoterapia boolean DEFAULT false,
    chemoterapia_leiras text,
    tnm_staging text,
    bno text,
    diagnozis text,
    baleset_idopont date,
    baleset_etiologiaja text,
    baleset_egyeb text,
    veleszuletett_rendellenessegek jsonb DEFAULT '[]'::jsonb,
    veleszuletett_mutetek_leirasa text,
    radioterapia_dozis_gy numeric,
    dohanyzas_szam_ertek numeric,
    CONSTRAINT patient_anamnesis_brown_fuggoleges_osztaly_check CHECK (((brown_fuggoleges_osztaly)::text = ANY ((ARRAY['1'::character varying, '2'::character varying, '3'::character varying, '4'::character varying])::text[]))),
    CONSTRAINT patient_anamnesis_brown_vizszintes_komponens_check CHECK (((brown_vizszintes_komponens)::text = ANY ((ARRAY['a'::character varying, 'b'::character varying, 'c'::character varying])::text[]))),
    CONSTRAINT patient_anamnesis_fabian_fejerdy_protetikai_osztaly_also_check CHECK (((fabian_fejerdy_protetikai_osztaly_also)::text = ANY ((ARRAY['0'::character varying, '1A'::character varying, '1B'::character varying, '2A'::character varying, '2A/1'::character varying, '2B'::character varying, '3'::character varying, 'T'::character varying])::text[]))),
    CONSTRAINT patient_anamnesis_fabian_fejerdy_protetikai_osztaly_check CHECK (((fabian_fejerdy_protetikai_osztaly)::text = ANY ((ARRAY['0'::character varying, '1A'::character varying, '1B'::character varying, '2A'::character varying, '2A/1'::character varying, '2B'::character varying, '3'::character varying, 'T'::character varying])::text[]))),
    CONSTRAINT patient_anamnesis_fabian_fejerdy_protetikai_osztaly_felso_check CHECK (((fabian_fejerdy_protetikai_osztaly_felso)::text = ANY ((ARRAY['0'::character varying, '1A'::character varying, '1B'::character varying, '2A'::character varying, '2A/1'::character varying, '2B'::character varying, '3'::character varying, 'T'::character varying])::text[]))),
    CONSTRAINT patient_anamnesis_kezelesre_erkezes_indoka_check CHECK (((kezelesre_erkezes_indoka)::text = ANY ((ARRAY['traumás sérülés'::character varying, 'veleszületett rendellenesség'::character varying, 'onkológiai kezelés utáni állapot'::character varying, 'nincs beutaló'::character varying])::text[]))),
    CONSTRAINT patient_anamnesis_kovacs_dobak_osztaly_check CHECK (((kovacs_dobak_osztaly)::text = ANY ((ARRAY['1'::character varying, '2'::character varying, '3'::character varying, '4'::character varying, '5'::character varying])::text[]))),
    CONSTRAINT patient_anamnesis_nyalmirigy_allapot_check CHECK (((nyalmirigy_allapot)::text = ANY ((ARRAY['hiposzaliváció'::character varying, 'hiperszaliváció'::character varying, 'Nem számol be eltérésről'::character varying])::text[])))
);


