    CONSTRAINT patient_consent_events_event_type_check CHECK (((event_type)::text = ANY ((ARRAY['pending'::character varying, 'granted'::character varying, 'withdrawn'::character varying, 'expired'::character varying, 'reconsent_requested'::character varying, 'declined'::character varying])::text[])))
);


