--

COMMENT ON COLUMN public.patient_stages.stage IS 'Stádium: uj_beteg, onkologiai_kezeles_kesz, arajanlatra_var, implantacios_sebeszi_tervezesre_var, fogpotlasra_var, fogpotlas_keszul, fogpotlas_kesz, gondozas_alatt';


