--

COMMENT ON COLUMN public.patient_stages.created_by IS 'Email cím vagy system - ki hozta létre a bejegyzést';


--
-- Name: patient_current_stage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.patient_current_stage AS
 SELECT DISTINCT ON (patient_id) patient_id,
    episode_id,
    stage,
    stage_date,
    notes,
    created_at,
    created_by
   FROM public.patient_stages
  ORDER BY patient_id, stage_date DESC;


