    CONSTRAINT patient_episodes_reason_check CHECK (((reason)::text = ANY ((ARRAY['traumás sérülés'::character varying, 'veleszületett rendellenesség'::character varying, 'onkológiai kezelés utáni állapot'::character varying])::text[]))),
    CONSTRAINT patient_episodes_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'closed'::character varying, 'paused'::character varying])::text[]))),
    CONSTRAINT patient_episodes_trigger_type_check CHECK (((trigger_type)::text = ANY ((ARRAY['recidiva'::character varying, 'fogelvesztes'::character varying, 'potlasvesztes'::character varying, 'kontrollbol_uj_panasz'::character varying, 'egyeb'::character varying])::text[])))
);


