    id uuid DEFAULT gen_random_uuid() NOT NULL,
    patient_id uuid NOT NULL,
    field_key text NOT NULL,
    reason text,
    set_by_user_id uuid,
    set_at timestamp with time zone DEFAULT now() NOT NULL,
    reason_code text DEFAULT 'nem_alkalmazhato'::text NOT NULL,
    CONSTRAINT patient_field_na_reason_code_check CHECK ((reason_code = ANY (ARRAY['nem_alkalmazhato'::text, 'nem_ismert'::text, 'beteg_megtagadta'::text, 'meg_nem_kerdeztek'::text])))
);


