--
-- Name: patients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.patients (
    id uuid DEFAULT public.generate_uuid() NOT NULL,
    nev character varying(255),
    taj character varying(20),
    telefonszam character varying(50),
    szuletesi_datum date,
    nem character varying(10),
    email character varying(255),
    cim text,
    varos character varying(100),
    iranyitoszam character varying(10),
    kezeleoorvos character varying(100),
    kezeleoorvos_intezete character varying(255),
    felvetel_datuma date,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    created_by character varying(255),
    updated_by character varying(255),
    intake_status character varying(30) DEFAULT 'JUST_REGISTERED'::character varying,
    arajanlatkero_szoveg text,
    arajanlatkero_datuma date,
    halal_datum date,
    kezeleoorvos_user_id uuid,
    domain_revision bigint DEFAULT 1 NOT NULL,
    recorded_at timestamp with time zone,
    effective_at timestamp with time zone,
    exported_at timestamp with time zone,
    legacy_compliance_status character varying(32) DEFAULT 'LEGACY_UNVERIFIED'::character varying NOT NULL,
    consent_status character varying(32) DEFAULT 'unknown'::character varying,
    consent_version_id uuid,
    consent_granted_at timestamp with time zone,
    consent_withdrawn_at timestamp with time zone,
    research_usable_until timestamp with time zone,
    torvenyes_kepviselo_nev character varying(255),
    torvenyes_kepviselo_kapcsolat character varying(64),
    torvenyes_kepviselo_email character varying(255),
    kezeleoorvos_assigned_at timestamp with time zone,
    kezeleoorvos_assigned_by uuid,
    portal_display_scale text DEFAULT 'normal'::text NOT NULL,
    CONSTRAINT patients_consent_status_check CHECK (((consent_status IS NULL) OR ((consent_status)::text = ANY ((ARRAY['unknown'::character varying, 'pending'::character varying, 'granted'::character varying, 'withdrawn'::character varying, 'expired'::character varying, 'declined'::character varying])::text[])))),
    CONSTRAINT patients_intake_status_check CHECK (((intake_status)::text = ANY ((ARRAY['JUST_REGISTERED'::character varying, 'NEEDS_TRIAGE'::character varying, 'TRIAGED'::character varying, 'IN_CARE'::character varying])::text[]))),
    CONSTRAINT patients_nem_check CHECK (((nem IS NULL) OR ((nem)::text = ANY ((ARRAY['ferfi'::character varying, 'no'::character varying, 'nem_ismert'::character varying])::text[])))),
    CONSTRAINT patients_portal_display_scale_check CHECK ((portal_display_scale = ANY (ARRAY['normal'::text, 'nagy'::text, 'extra'::text])))
);


--
-- Name: TABLE patients; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.patients IS 'Betegek főtáblája - maxillofacialis rehabilitációs adatok';


