--

COMMENT ON COLUMN public.patients.created_at IS 'Rekord létrehozásának időpontja';


--
-- Name: COLUMN patients.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.updated_at IS 'Rekord utolsó frissítésének időpontja';


--
-- Name: COLUMN patients.created_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.created_by IS 'A felhasználó email címe, aki a rekordot létrehozta';


--
-- Name: COLUMN patients.updated_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.updated_by IS 'A felhasználó email címe, aki utoljára módosította';


--
-- Name: COLUMN patients.arajanlatkero_szoveg; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.arajanlatkero_szoveg IS 'Árajánlatkérő szabadszavas mező tartalma';


--
-- Name: COLUMN patients.arajanlatkero_datuma; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.arajanlatkero_datuma IS 'Árajánlatkérő dátuma (egy héttel az ajánlatkérés után)';


--
-- Name: COLUMN patients.halal_datum; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.halal_datum IS 'Páciens halálának dátuma (opcionális)';


--
-- Name: COLUMN patients.kezeleoorvos_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.kezeleoorvos_user_id IS 'Aktuális kezelőorvos user_id (canonical). Recompute logika tartja karban: B-eset = legutóbb nyitott aktív epizód assigned_provider_id, A-eset = legközelebbi nem-cancelled/rejected appointment dentist_email → users.id. Lásd lib/recompute-kezeleoorvos.ts. A régi patients.kezeleoorvos VARCHAR mező backward-compat: minden write-tal együtt frissül a users.doktor_neve aktuális értékére.';


--
-- Name: COLUMN patients.domain_revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.domain_revision IS 'Optimistic locking revision; incremented on clinical writes.';


--
-- Name: COLUMN patients.legacy_compliance_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.legacy_compliance_status IS 'LEGACY_UNVERIFIED | IMPORTED_LEGACY | VERIFIED — transitional backfill states.';


--
-- Name: COLUMN patients.kezeleoorvos_assigned_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.kezeleoorvos_assigned_at IS 'Kézi kezelőorvos-hozzárendelés időpontja. NEM NULL → a recompute nem írja felül (ragadós elköteleződés). NULL → seedelhető automatikusan.';


--
-- Name: COLUMN patients.kezeleoorvos_assigned_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.patients.kezeleoorvos_assigned_by IS 'Ki rendelte hozzá kézzel a kezelőorvost (users.id). NULL, ha a befagyasztott migrált értékről van szó vagy a hozzárendelő user törlődött.';


--
-- Name: patients_full; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.patients_full AS
 SELECT p.id,
    p.nev,
    p.taj,
    p.telefonszam,
    p.szuletesi_datum,
    p.nem,
    p.email,
    p.cim,
    p.varos,
    p.iranyitoszam,
    p.kezeleoorvos,
    p.kezeleoorvos_intezete,
    p.felvetel_datuma,
    p.halal_datum,
    p.intake_status,
    p.created_at,
    p.updated_at,
    p.created_by,
    p.updated_by,
    r.beutalo_orvos,
    r.beutalo_intezmeny,
    r.beutalo_indokolas,
    r.primer_mutet_leirasa,
    r.mutet_ideje,
    r.szovettani_diagnozis,
    r.nyaki_blokkdisszekcio,
    a.kezelesre_erkezes_indoka,
    a.alkoholfogyasztas,
    a.dohanyzas_szam,
    a.maxilladefektus_van,
    a.brown_fuggoleges_osztaly,
    a.brown_vizszintes_komponens,
    a.mandibuladefektus_van,
    a.kovacs_dobak_osztaly,
    a.nyelvmozgasok_akadalyozottak,
    a.gombocos_beszed,
    a.nyalmirigy_allapot,
    a.fabian_fejerdy_protetikai_osztaly,
    a.fabian_fejerdy_protetikai_osztaly_felso,
    a.fabian_fejerdy_protetikai_osztaly_also,
    a.radioterapia,
    a.radioterapia_dozis,
    a.radioterapia_datum_intervallum,
    a.chemoterapia,
    a.chemoterapia_leiras,
    a.tnm_staging,
    a.bno,
    a.diagnozis,
    a.baleset_idopont,
    a.baleset_etiologiaja,
    a.baleset_egyeb,
    a.veleszuletett_rendellenessegek,
    a.veleszuletett_mutetek_leirasa,
    d.meglevo_fogak,
    d.meglevo_implantatumok,
    d.nem_ismert_poziciokban_implantatum,
    d.nem_ismert_poziciokban_implantatum_reszletek,
    d.felso_fogpotlas_van,
    d.felso_fogpotlas_mikor,
    d.felso_fogpotlas_keszito,
    d.felso_fogpotlas_elegedett,
    d.felso_fogpotlas_problema,
    d.felso_fogpotlas_tipus,
    d.also_fogpotlas_van,
    d.also_fogpotlas_mikor,
    d.also_fogpotlas_keszito,
    d.also_fogpotlas_elegedett,
    d.also_fogpotlas_problema,
    d.also_fogpotlas_tipus,
    t.kezelesi_terv_felso,
    t.kezelesi_terv_also,
    t.kezelesi_terv_arcot_erinto,
    t.kortorteneti_osszefoglalo,
    t.kezelesi_terv_melleklet,
    t.szakorvosi_velemeny,
    p.torvenyes_kepviselo_nev,
    p.torvenyes_kepviselo_kapcsolat,
    p.torvenyes_kepviselo_email
   FROM ((((public.patients p
     LEFT JOIN public.patient_referral r ON ((r.patient_id = p.id)))
     LEFT JOIN public.patient_anamnesis a ON ((a.patient_id = p.id)))
     LEFT JOIN public.patient_dental_status d ON ((d.patient_id = p.id)))
     LEFT JOIN public.patient_treatment_plans t ON ((t.patient_id = p.id)));


