--
-- Name: research_patient_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.research_patient_view AS
 SELECT p.id AS patient_id,
        CASE
            WHEN (p.szuletesi_datum IS NOT NULL) THEN (((EXTRACT(year FROM age((CURRENT_DATE)::timestamp with time zone, (p.szuletesi_datum)::timestamp with time zone)))::integer / 5) * 5)
            ELSE NULL::integer
        END AS age_band_start,
    "left"((COALESCE(p.iranyitoszam, ''::character varying))::text, 2) AS region_prefix,
    p.nem,
    a.kezelesre_erkezes_indoka,
    p.domain_revision,
    p.legacy_compliance_status
   FROM (public.patients p
     LEFT JOIN public.patient_anamnesis a ON ((a.patient_id = p.id)));


--
-- Name: VIEW research_patient_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.research_patient_view IS 'De-identified patient projection for research exports; no direct PHI fields.';


