-- Name: slot_intents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.slot_intents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    episode_id uuid NOT NULL,
    step_code character varying(80) NOT NULL,
    window_start timestamp with time zone,
    window_end timestamp with time zone,
    duration_minutes integer NOT NULL,
    pool character varying(16) NOT NULL,
    state character varying(16) DEFAULT 'open'::character varying NOT NULL,
    priority integer DEFAULT 0,
    suggested_start timestamp with time zone,
    suggested_end timestamp with time zone,
    slot_hold_expires_at timestamp with time zone,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    source_pathway_hash character varying(64),
    step_seq integer DEFAULT 0 NOT NULL,
    work_phase_id uuid,
    CONSTRAINT slot_intents_pool_check CHECK (((pool)::text = ANY ((ARRAY['consult'::character varying, 'work'::character varying, 'control'::character varying])::text[]))),
    CONSTRAINT slot_intents_state_check CHECK (((state)::text = ANY ((ARRAY['open'::character varying, 'converted'::character varying, 'cancelled'::character varying, 'expired'::character varying])::text[])))
);


--
-- Name: COLUMN slot_intents.work_phase_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.slot_intents.work_phase_id IS 'Canonical link to episode_work_phases.id. Nullable for backward compat. New intents should be created with this set; legacy rows remain keyed via step_code.';


--
-- Name: slot_purpose_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.slot_purpose_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slot_id uuid NOT NULL,
    old_purpose character varying(16),
    new_purpose character varying(16) NOT NULL,
    reason text,
    job_run_id character varying(100),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);


