    episode_id uuid,
    CONSTRAINT tooth_treatments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'episode_linked'::text, 'completed'::text]))),
    CONSTRAINT tooth_treatments_tooth_number_check CHECK (((tooth_number >= 11) AND (tooth_number <= 48)))
);


