--
-- Name: user_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assignee_kind text NOT NULL,
    assignee_user_id uuid,
    assignee_patient_id uuid,
    patient_id uuid,
    task_type text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    title text NOT NULL,
    description text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_message_id uuid,
    source_doctor_message_id uuid,
    created_by_user_id uuid NOT NULL,
    due_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    viewed_at timestamp with time zone,
    CONSTRAINT user_tasks_assignee_filled_check CHECK ((((assignee_kind = 'staff'::text) AND (assignee_user_id IS NOT NULL) AND (assignee_patient_id IS NULL)) OR ((assignee_kind = 'patient'::text) AND (assignee_patient_id IS NOT NULL) AND (assignee_user_id IS NULL)))),
    CONSTRAINT user_tasks_assignee_kind_check CHECK ((assignee_kind = ANY (ARRAY['staff'::text, 'patient'::text]))),
    CONSTRAINT user_tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text, 'cancelled'::text]))),
    CONSTRAINT user_tasks_task_type_check CHECK ((task_type = ANY (ARRAY['document_upload'::text, 'ohip14'::text, 'manual'::text, 'meeting_action'::text, 'staff_registration_review'::text, 'missing_data'::text])))
);


--
-- Name: COLUMN user_tasks.viewed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.user_tasks.viewed_at IS 'When the assignee first opened the task list (staff); NULL means not yet seen.';


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email character varying(255) NOT NULL,
    password_hash character varying(255) NOT NULL,
    role character varying(20) DEFAULT 'editor'::character varying,
    active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    last_login timestamp with time zone,
    doktor_neve character varying(255),
    intezmeny character varying(255),
    hozzaferes_indokolas text,
    google_calendar_source_calendar_id character varying(255) DEFAULT 'primary'::character varying,
    google_calendar_target_calendar_id character varying(255) DEFAULT 'primary'::character varying,
    google_calendar_status character varying(50) DEFAULT 'active'::character varying,
    google_calendar_last_error_code character varying(100),
    google_calendar_last_error_at timestamp with time zone,
    google_calendar_refresh_token text,
    google_calendar_access_token text,
    google_calendar_token_expires_at timestamp with time zone,
    google_calendar_enabled boolean DEFAULT false,
    google_calendar_email character varying(255),
    password_reset_token character varying(255),
    password_reset_expires timestamp with time zone,
    restricted_view boolean DEFAULT false,
    CONSTRAINT users_role_check CHECK (((role)::text = ANY ((ARRAY['admin'::character varying, 'fogpótlástanász'::character varying, 'technikus'::character varying, 'beutalo_orvos'::character varying])::text[])))
);


